179	    /**
180	     * Determines whether the given city already contains the maximum number of owners permitted
181	     * per city. Owners are counted by matching their city ignoring letter case. A {@code null}
182	     * city is never considered to have reached the limit.
183	     *
184	     * @param city the city of the owner about to be created
185	     * @return {@code true} if at least {@link #MAX_OWNERS_PER_CITY} owners already reside in the
186	     *         given city
187	     */
188	    private boolean isCityOwnerLimitReached(String city) {
189	        if (city == null) {
190	            return false;
191	        }
192	        long ownersInCity = this.clinicService.findAllOwners().stream()
193	            .filter(existing -> existing.getCity() != null
194	                && existing.getCity().equalsIgnoreCase(city))
195	            .count();
