212	    /**
213	     * Canonicalises a telephone number by stripping every character that is not a digit
214	     * (for example spaces, dashes and parentheses), so that {@code "(613) 555-0100"} and
215	     * {@code "6135550100"} are treated as the same number. This is the form persisted for
216	     * an owner and used for the telephone-uniqueness check.
217	     *
218	     * @param telephone the raw telephone value, possibly {@code null}
219	     * @return the digits-only telephone, or {@code null} if {@code telephone} was {@code null}
220	     */
221	    private static String normalizeTelephone(String telephone) {
222	        if (telephone == null) {
223	            return null;
224	        }
225	        return telephone.replaceAll("[^0-9]", "");
226	    }
227	
228	    /**
229	     * Determines whether any other owner already uses the candidate's email address.
230	     * An absent or blank email is never considered a duplicate. The comparison ignores
231	     * letter case and surrounding or repeated whitespace.
232	     *
233	     * @param candidate the owner about to be created
234	     * @return {@code true} if an owner with the same email is already present in the data store
235	     */
236	    private boolean isDuplicateEmail(Owner candidate) {
237	        String email = normalize(candidate.getEmail());
238	        if (email == null || email.isBlank()) {
239	            return false;
240	        }
241	        return this.clinicService.findAllOwners().stream()
242	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
243	    }
244	
245	    /**
246	     * Builds the customer code for a newly created owner, formatted as
247	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of
248	     * owners already present in the same city, zero-padded to four digits
249	     * (e.g. {@code 'LONDON-0007'}). Cities are matched ignoring letter case.
250	     *
251	     * @param city the city of the owner about to be created
252	     * @return the formatted customer code
253	     */
254	    /**
255	     * Resolves the city name to store for a newly created owner. The supplied city is
256	     * normalised to title case (each word's first letter upper-cased, the rest lower-cased),
257	     * so that {@code "new york"} and {@code "NEW YORK"} both become {@code "New York"}.
258	     * However, if an owner already exists in that city (matched ignoring letter case), that
259	     * existing owner's exact spelling of the city is reused instead, so a single canonical
260	     * spelling is kept per city (for example an existing {@code "McFarland"} is preserved
261	     * rather than being flattened to {@code "Mcfarland"}).
262	     *
263	     * @param city the raw city supplied for the owner about to be created
264	     * @return the existing owner's spelling if the city is already known, otherwise the
265	     *         title-cased city; {@code null} if {@code city} was {@code null}
266	     */
267	    private String resolveCity(String city) {
268	        if (city == null) {
269	            return null;
270	        }
271	        return this.clinicService.findAllOwners().stream()
272	            .map(Owner::getCity)
273	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
274	            .findFirst()
275	            .orElseGet(() -> titleCase(city));
276	    }
277	
278	    /**
279	     * Converts a city name to title case: each whitespace-separated word has its first letter
280	     * upper-cased and its remaining letters lower-cased, while the original whitespace is left
281	     * untouched. For example {@code "san   FRANCISCO"} becomes {@code "San   Francisco"}.
282	     *
283	     * @param city the city to title-case
284	     * @return the title-cased city
285	     */
286	    private static String titleCase(String city) {
287	        StringBuilder result = new StringBuilder(city.length());
288	        boolean startOfWord = true;
289	        for (int i = 0; i < city.length(); i++) {
290	            char c = city.charAt(i);
291	            if (Character.isWhitespace(c)) {
292	                startOfWord = true;
293	                result.append(c);
294	            } else if (startOfWord) {
295	                result.append(Character.toTitleCase(c));
296	                startOfWord = false;
297	            } else {
298	                result.append(Character.toLowerCase(c));
299	            }
300	        }
301	        return result.toString();
302	    }
303	
304	    private String nextCustomerCode(String city) {
305	        long ownersInCity = this.clinicService.findAllOwners().stream()
306	            .filter(existing -> existing.getCity() != null
307	                && existing.getCity().equalsIgnoreCase(city))
308	            .count();
309	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
310	    }
311	
312	    /**
313	     * Canonicalises a value for duplicate detection so that comparisons ignore letter
314	     * case and surrounding or repeated whitespace. Surrounding whitespace is stripped,
315	     * any run of internal whitespace is collapsed to a single space, and the result is
316	     * lower-cased. For example {@code "  john   smith "} and {@code "John Smith"} both
317	     * normalise to {@code "john smith"}.
318	     *
319	     * @param value the raw value, possibly {@code null}
320	     * @return the normalised value, or {@code null} if {@code value} was {@code null}
321	     */
322	    private static String normalize(String value) {
323	        if (value == null) {
324	            return null;
325	        }
326	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
327	    }
